#!/usr/bin/env python3
"""
juniper_terrestrial_timepiece_narrator.narrator
~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
Terrestrial Timepiece Narrator Engine.
Concise event narrator for DJ bot audio buffering.
"""

import os
import time
import wave
import json
import requests
import threading
from datetime import datetime
import pyttsx3

CACHE_DIR = os.path.join(os.path.dirname(__file__), "narration_cache")
os.makedirs(CACHE_DIR, exist_ok=True)

TIMEPIECE_URL = os.environ.get("TIMEPIECE_URL", "http://127.0.0.1:5008/api/timepiece_state")


WHEEL_OF_YEAR_EVENTS = [
    (0.000, "Vernal Equinox", "Now is the vernal equinox."),
    (0.125, "Beltane", "Now is beltane."),
    (0.250, "Summer Solstice", "Now is the summer solstice."),
    (0.375, "Lughnasadh", "Now is lughnasadh."),
    (0.500, "Autumnal Equinox", "Now is the autumnal equinox."),
    (0.625, "Samhain", "Now is samhain."),
    (0.750, "Winter Solstice", "Now is the winter solstice."),
    (0.875, "Imbolc", "Now is imbolc.")
]

LUNAR_PHASE_EVENTS = [
    (0.000, "New Moon", "Now is the new moon."),
    (0.125, "Waxing Crescent", "Now is the waxing crescent moon."),
    (0.250, "First Quarter", "Now is the first quarter moon."),
    (0.375, "Waxing Gibbous", "Now is the waxing gibbous moon."),
    (0.500, "Full Moon", "Now is the full moon."),
    (0.625, "Waning Gibbous", "Now is the waning gibbous moon."),
    (0.750, "Third Quarter", "Now is the third quarter moon."),
    (0.875, "Waning Crescent", "Now is the waning crescent moon.")
]


class TerrestrialTimepieceNarrator:
    def __init__(self, timepiece_url: str = TIMEPIECE_URL):
        self.timepiece_url = timepiece_url
        self.session = requests.Session()
        self.lock = threading.Lock()

        self.tts_engine = pyttsx3.init()
        self.tts_engine.setProperty('rate', 145)
        self._configure_voice()

        self.last_std_hour = -1
        self.last_wheel_bucket = -1
        self.last_lunar_bucket = -1
        self.last_tidal_bucket = -1
        self.last_roman_hour = -1

        self.current_timepiece_state = None
        self.history = []

        self.app_state = {
            "status": "Listening for events...",
            "last_narration": "",
            "audio_file": None,
            "audio_id": 0,
            "current_event": "Idle",
            "timepiece_data": None,
            "history": []
        }

    def _configure_voice(self):
        try:
            voices = self.tts_engine.getProperty('voices')
            if not voices:
                return
            selected_voice = voices[0].id
            for v in voices:
                v_name = getattr(v, 'name', '').lower()
                if 'zira' in v_name or 'samantha' in v_name or 'victoria' in v_name or 'alex' in v_name:
                    selected_voice = v.id
                    break
            self.tts_engine.setProperty('voice', selected_voice)
        except Exception as e:
            print(f"[NARRATOR VOICE] Warning configuring voice: {e}")

    def _pad_wav_with_silence(self, filepath: str, silence_duration_sec: float = 0.25):
        try:
            with wave.open(filepath, 'rb') as f:
                params = f.getparams()
                frames = f.readframes(params.nframes)

            silence_frames = int(params.framerate * silence_duration_sec)
            zero_sample = b'\x00' * (params.sampwidth * params.nchannels)
            silence_bytes = zero_sample * silence_frames

            with wave.open(filepath, 'wb') as f:
                f.setparams(params)
                f.writeframes(frames + silence_bytes)
        except Exception as e:
            print(f"[AUDIO PADDING] Error padding audio: {e}")

    def generate_tts_wav(self, text: str, filename: str) -> str:
        filepath = os.path.join(CACHE_DIR, filename)
        self.tts_engine.save_to_file(text, filepath)
        self.tts_engine.runAndWait()
        self._pad_wav_with_silence(filepath, silence_duration_sec=0.25)
        return filename

    def get_wav_duration(self, filepath: str) -> float:
        try:
            with wave.open(filepath, 'r') as f:
                frames = f.getnframes()
                rate = f.getframerate()
                return frames / float(rate)
        except Exception:
            return 2.0

    def speak_event(self, event_title: str, script_text: str, prefix: str = "event"):
        print(f"[TIMEPIECE EVENT: {event_title}] {script_text}")
        filename = f"{prefix}_{int(time.time())}.wav"
        filepath = os.path.join(CACHE_DIR, filename)

        self.generate_tts_wav(script_text, filename)
        duration = self.get_wav_duration(filepath)

        record = {
            "timestamp": time.strftime("%H:%M:%S UTC", time.gmtime()),
            "event": event_title,
            "text": script_text,
            "filename": filename
        }

        with self.lock:
            self.history.insert(0, record)
            if len(self.history) > 30:
                self.history.pop()

            self.app_state["status"] = f"Announcing: {event_title}"
            self.app_state["last_narration"] = script_text
            self.app_state["current_event"] = event_title
            self.app_state["audio_file"] = filename
            self.app_state["audio_id"] += 1
            self.app_state["history"] = list(self.history)

        time.sleep(duration)

        with self.lock:
            self.app_state["status"] = "Listening for timepiece events..."

    def fetch_timepiece_state(self) -> dict:
        """Polls clock state via persistent HTTP session."""
        try:
            resp = self.session.get(self.timepiece_url, timeout=5.0)
            if resp.status_code == 200:
                return resp.json()
        except Exception:
            pass
        return None

    def evaluate_events(self, state: dict):
        server_ts = state.get("server_time", time.time())
        std_h = datetime.fromtimestamp(server_ts).hour

        season_prog = state.get("season_progress", 0.0) % 1.0
        moon_prog = state.get("moon_progress", 0.0) % 1.0

        roman = state.get("roman", {})
        tidal = state.get("tidal", {})

        rom_h = int(roman.get("h", 0))
        tide_h = tidal.get("h", 0.0)

        wheel_bucket = int(((season_prog + 0.03125) % 1.0) / 0.125)
        lunar_bucket = int(((moon_prog + 0.03125) % 1.0) / 0.125)

        if tide_h < 0.5 or tide_h > 11.5:
            tide_bucket = 0  # High tide
        elif 5.5 <= tide_h <= 6.5:
            tide_bucket = 1  # Low tide
        else:
            tide_bucket = 2  # Mid tide

        # First boot initialization: seed state silently without triggering audio
        if self.last_std_hour == -1:
            self.last_std_hour = std_h
            self.last_roman_hour = rom_h
            self.last_tidal_bucket = tide_bucket
            self.last_lunar_bucket = lunar_bucket
            self.last_wheel_bucket = wheel_bucket
            return

        # 1. STANDARD TOP-OF-THE-HOUR TIME
        if std_h != self.last_std_hour:
            script = f"Time is now {std_h:02d}00 hours."
            self.speak_event("Standard Hour", script, prefix="std")
            self.last_std_hour = std_h

        # 2. SOLAR / CELESTIAL TRANSITIONS
        if rom_h != self.last_roman_hour:
            if rom_h == 0:
                self.speak_event("Sunrise", "Now is sunrise.", prefix="roman")
            elif rom_h == 6:
                self.speak_event("High Noon", "Now is high noon.", prefix="roman")
            elif rom_h == 12:
                self.speak_event("Sunset", "Now is sunset.", prefix="roman")
            elif rom_h == 18:
                self.speak_event("Solar Midnight", "Now is solar midnight.", prefix="roman")
            self.last_roman_hour = rom_h

        # 3. TIDAL TIME
        if tide_bucket != self.last_tidal_bucket:
            if tide_bucket == 0:
                self.speak_event("High Tide", "Now is high tide.", prefix="tidal")
            elif tide_bucket == 1:
                self.speak_event("Low Tide", "Now is low tide.", prefix="tidal")
            self.last_tidal_bucket = tide_bucket

        # 4. LUNAR TIME
        if lunar_bucket != self.last_lunar_bucket:
            event_title, script_text = LUNAR_PHASE_EVENTS[lunar_bucket][1:]
            self.speak_event(f"Lunar: {event_title}", script_text, prefix="lunar")
            self.last_lunar_bucket = lunar_bucket

        # 5. ORBITAL TIME / WHEEL OF THE YEAR
        if wheel_bucket != self.last_wheel_bucket:
            event_title, script_text = WHEEL_OF_YEAR_EVENTS[wheel_bucket][1:]
            self.speak_event(f"Orbital: {event_title}", script_text, prefix="season")
            self.last_wheel_bucket = wheel_bucket

    def start_polling_loop(self):
        print(f"[NARRATOR] Polling Terrestrial Timepiece at {self.timepiece_url}...")
        while True:
            state = self.fetch_timepiece_state()
            if state:
                with self.lock:
                    self.current_timepiece_state = state
                    self.app_state["timepiece_data"] = state
                    if self.app_state["status"].startswith("Initializing"):
                        self.app_state["status"] = "Listening for timepiece events..."
                self.evaluate_events(state)
            else:
                with self.lock:
                    self.app_state["status"] = "Timepiece server offline. Retrying..."
            time.sleep(1.0)
